function cfB64Encode(s){
  var bytes=cfUtf8Bytes(s), tbl='ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/', out='';
  for(var i=0;i<bytes.length;i+=3){
    var b0=bytes[i], b1=bytes[i+1], b2=bytes[i+2];
    out += tbl[b0>>2] + tbl[((b0&3)<<4)|((b1===undefined?0:b1)>>4)];
    out += (b1===undefined)?'=':tbl[((b1&15)<<2)|((b2===undefined?0:b2)>>6)];
    out += (b2===undefined)?'=':tbl[b2&63];
  }
  return out;
}
function cfB64Decode(s){
  var tbl='ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/';
  var clean=String(s).replace(/[\s]/g,'').replace(/-/g,'+').replace(/_/g,'/').replace(/=+$/,'');
  if(/[^A-Za-z0-9+/]/.test(clean)) return null;
  var bytes=[], buf=0, bits=0;
  for(var i=0;i<clean.length;i++){
    buf=(buf<<6)|tbl.indexOf(clean[i]); bits+=6;
    if(bits>=8){ bits-=8; bytes.push((buf>>bits)&255); }
  }
  return cfBytesUtf8(bytes);
}
function cfUtf8Bytes(s){
  var out=[];
  for(var i=0;i<s.length;i++){
    var c=s.charCodeAt(i);
    if(c<128) out.push(c);
    else if(c<2048){ out.push(192|(c>>6), 128|(c&63)); }
    else if(c>=55296 && c<56320 && i+1<s.length){
      var c2=s.charCodeAt(i+1), cp=65536+((c-55296)<<10)+(c2-56320); i++;
      out.push(240|(cp>>18), 128|((cp>>12)&63), 128|((cp>>6)&63), 128|(cp&63));
    } else { out.push(224|(c>>12), 128|((c>>6)&63), 128|(c&63)); }
  }
  return out;
}
function cfBytesUtf8(b){
  var out='', i=0;
  while(i<b.length){
    var c=b[i];
    if(c<128){ out+=String.fromCharCode(c); i++; }
    else if(c<224){ out+=String.fromCharCode(((c&31)<<6)|(b[i+1]&63)); i+=2; }
    else if(c<240){ out+=String.fromCharCode(((c&15)<<12)|((b[i+1]&63)<<6)|(b[i+2]&63)); i+=3; }
    else {
      var cp=((c&7)<<18)|((b[i+1]&63)<<12)|((b[i+2]&63)<<6)|(b[i+3]&63); cp-=65536;
      out+=String.fromCharCode(55296+(cp>>10), 56320+(cp&1023)); i+=4;
    }
  }
  return out;
}
function cfHexEncode(s){
  var b=cfUtf8Bytes(s), out=[];
  for(var i=0;i<b.length;i++) out.push(('0'+b[i].toString(16)).slice(-2));
  return out.join(' ');
}
function cfHexDecode(s){
  var clean=String(s).replace(/0x/gi,'').replace(/[\s,:]/g,'');
  if(clean.length%2) return null;
  if(/[^0-9a-fA-F]/.test(clean)) return null;
  var b=[];
  for(var i=0;i<clean.length;i+=2) b.push(parseInt(clean.substr(i,2),16));
  return cfBytesUtf8(b);
}
function cfRot(s, n){
  n=((n%26)+26)%26;
  return String(s).replace(/[a-zA-Z]/g, function(ch){
    var base = ch<='Z' ? 65 : 97;
    return String.fromCharCode((ch.charCodeAt(0)-base+n)%26+base);
  });
}
function cfUrlEncode(s){ return encodeURIComponent(String(s)); }
function cfUrlDecode(s){ try { return decodeURIComponent(String(s)); } catch(e){ return null; } }
function cfReverse(s){ return String(s).split('').reverse().join(''); }
function cfXor(s, key){
  if(!key) return s;
  var out='';
  for(var i=0;i<s.length;i++) out+=String.fromCharCode(s.charCodeAt(i)^key.charCodeAt(i%key.length));
  return out;
}
function cfEntropy(s){
  if(!s || !s.length) return 0;
  var freq={}, i;
  for(i=0;i<s.length;i++) freq[s[i]]=(freq[s[i]]||0)+1;
  var h=0;
  for(var k in freq){ var p=freq[k]/s.length; h -= p*Math.log(p)/Math.LN2; }
  return Math.round(h*1000)/1000;
}
var CF_OPS = {
  b64e:{label:'Base64 编码', fn:function(s){ return cfB64Encode(s); }},
  b64d:{label:'Base64 解码', fn:function(s){ return cfB64Decode(s); }},
  hexe:{label:'Hex 编码', fn:function(s){ return cfHexEncode(s); }},
  hexd:{label:'Hex 解码', fn:function(s){ return cfHexDecode(s); }},
  urle:{label:'URL 编码', fn:function(s){ return cfUrlEncode(s); }},
  urld:{label:'URL 解码', fn:function(s){ return cfUrlDecode(s); }},
  rot13:{label:'ROT13', fn:function(s){ return cfRot(s,13); }},
  rev:{label:'反转字符串', fn:function(s){ return cfReverse(s); }},
  upper:{label:'转大写', fn:function(s){ return String(s).toUpperCase(); }},
  lower:{label:'转小写', fn:function(s){ return String(s).toLowerCase(); }},
  trim:{label:'去除首尾空白', fn:function(s){ return String(s).trim(); }},
  strip:{label:'删除所有空白', fn:function(s){ return String(s).replace(/\s+/g,''); }},
  xor:{label:'XOR（需密钥）', fn:function(s,arg){ return cfXor(s,arg||''); }}
};
function cfRun(input, recipe){
  var cur=String(input==null?'':input), steps=[];
  if(!recipe || !recipe.length) return { error:null, output:cur, steps:[] };
  for(var i=0;i<recipe.length;i++){
    var st=recipe[i], op=CF_OPS[st.op];
    if(!op) return { error:'未知操作：'+st.op, output:null, steps:steps, failAt:i };
    var next;
    try { next = op.fn(cur, st.arg); } catch(e){ next = null; }
    if(next===null || next===undefined)
      return { error:'第 '+(i+1)+' 步「'+op.label+'」失败：输入格式不匹配', output:null, steps:steps, failAt:i };
    cur = next;
    steps.push({ op:st.op, label:op.label, out:cur, len:cur.length });
  }
  return { error:null, output:cur, steps:steps };
}
function cfParseRecipe(text){
  var lines=String(text||'').split(/\n+/), out=[];
  for(var i=0;i<lines.length;i++){
    var l=lines[i].trim();
    if(!l || l.charAt(0)==='#') continue;
    var sp=l.indexOf(' '), op = sp<0 ? l : l.slice(0,sp), arg = sp<0 ? '' : l.slice(sp+1).trim();
    out.push({ op:op, arg:arg });
  }
  return out;
}
if (typeof module !== 'undefined' && module.exports) {
  module.exports = { cfB64Encode:cfB64Encode, cfB64Decode:cfB64Decode, cfHexEncode:cfHexEncode,
    cfHexDecode:cfHexDecode, cfRot:cfRot, cfUrlEncode:cfUrlEncode, cfUrlDecode:cfUrlDecode,
    cfReverse:cfReverse, cfXor:cfXor, cfEntropy:cfEntropy, cfRun:cfRun, cfParseRecipe:cfParseRecipe, CF_OPS:CF_OPS };
}
if (typeof window !== 'undefined') {
